@startuml

class SensorController {
  + systemName : string
  + querySensorValues(sensorId : int) : float
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalPowerConsumption : float
}

enum Unit {
  CELSIUS
  WATT
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert() : void
}

class Admin {
  + hasAdminRights : boolean
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "*" -- "1" SensorController
Inhabitant "1" -- "1..*" Room
Admin --|> Inhabitant
SensorController "1" -- "1" EMonitor
Sensor "1" *-- "1" SensorValue
Sensor "1" -- "0..1" SensorValue : lastValue
Sensor "1" -- "1" Room

@enduml

